void ButtonTest(int backValue, int maxBackValue)
{
    u8g2.clearBuffer();
    u8g2.setFontMode(1);
    u8g2.setBitmapMode(1);
    
    // Button Layout
    u8g2.drawXBMP(19, 9, 91, 53, image_Layer_6_bits);

    if(selectButtonHold()){
        // MiddlePress
        u8g2.drawFilledEllipse(64, 30, 10, 4);

    }

    if(rightButtonHold()){
        // PressRight
        u8g2.drawXBMP(80, 25, 28, 11, image_PressRight_bits);
    }
    
    if(leftButtonHold()){
        // PressLeft
        u8g2.drawXBMP(21, 25, 28, 11, image_PressLeft_bits);
    }

    if(upButtonHold()){
        // PressUp
        u8g2.drawXBMP(51, 11, 27, 14, image_PressUp_bits);
    }

    if(downButtonHold()){
        // PressDown
        u8g2.drawXBMP(52, 40, 27, 14, image_PressDown_bits);
    }
    
    u8g2.setFont(u8g2_font_4x6_tr);
    u8g2.drawStr(34, 6, "HOLD \"->\" to EXIT");

    u8g2.setDrawColor(2);
    int boxWidth = (backValue * 128)/maxBackValue;
    u8g2.drawBox(0, 0, boxWidth, 7);

    u8g2.sendBuffer();
}
